---
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"

import { toggleVariants, type ToggleVariantProps } from "./toggle-variants"

type Props = HTMLAttributes<"button"> &
  ToggleVariantProps & {
    defaultPressed?: boolean
    disabled?: boolean
  }

const {
  class: className,
  variant = "default",
  size = "default",
  defaultPressed,
  disabled,
  type = "button",
  ...props
} = Astro.props
---

<button
  data-slot="toggle"
  data-default-pressed={defaultPressed}
  data-disabled={disabled ? "true" : undefined}
  type={type}
  disabled={disabled}
  aria-pressed={defaultPressed === true ? "true" : "false"}
  class={cn(toggleVariants({ variant, size }), className)}
  {...props}
>
  <slot />
</button>

<script>
  import { create } from "@data-slot/toggle"

  import { initDataSlot } from "@/lib/data-slot"

  initDataSlot(create)
</script>

import { cva, type VariantProps } from "class-variance-authority"

export const toggleVariants = cva(
  "group/toggle hover:bg-muted hover:text-foreground focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 aria-pressed:bg-muted dark:aria-invalid:ring-destructive/40 inline-flex items-center justify-center gap-1 rounded-md text-sm font-medium whitespace-nowrap transition-[color,box-shadow] outline-none focus-visible:ring-[3px] disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline: "border-input hover:bg-muted border bg-transparent shadow-xs",
      },
      size: {
        default:
          "h-9 min-w-9 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        sm: "h-8 min-w-8 px-2.5 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5",
        lg: "h-10 min-w-10 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

export type ToggleVariantProps = VariantProps<typeof toggleVariants>

type Controller = { destroy(): void }

// Astro scripts run once; ClientRouter replaces their component roots on each page.
// Keep every controller until the swap so open portals and scroll locks are cleaned up.
const initializers = new Set<() => Controller[]>()

export function initDataSlot(create: () => Controller[]) {
  if (initializers.has(create)) return
  initializers.add(create)
  const controllers = new Set<Controller>()
  const init = () => {
    for (const controller of create()) controllers.add(controller)
  }

  document.addEventListener("astro:page-load", init)
  document.addEventListener("astro:before-swap", () => {
    for (const controller of [...controllers].reverse()) controller.destroy()
    controllers.clear()
  })
  init()
}
